L1: import { execFileSync } from "node:child_process";
L2: 
L3: /** 解析 `reg query ...Internet Settings` 输出中的 ProxyEnable / ProxyServer。 */
L4: export function parseRegistryProxy(text) {
L5:   const enable = /ProxyEnable\s+REG_DWORD\s+0x([0-9a-f]+)/i.exec(String(text ?? ""));
L6:   const server = /ProxyServer\s+REG_SZ\s+(.+)/i.exec(String(text ?? ""));
L7:   if (!server) return null;
L8:   return {
L9:     proxyEnable: enable ? parseInt(enable[1], 16) !== 0 : false,
L10:     proxyServer: server[1].trim(),
L11:   };
L12: }
L13: 
L14: function readWindowsRegistryProxy() {
L15:   try {
L16:     const out = execFileSync(
L17:       "reg",
L18:       ["query", "HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings"],
L19:       { encoding: "utf8", windowsHide: true }
L20:     );
L21:     return parseRegistryProxy(out);
L22:   } catch {
L23:     return null;
L24:   }
L25: }
L26: 
L27: function withScheme(v) {
L28:   return /^[a-z][a-z0-9+.-]*:\/\//i.test(v) ? v : `http://${v}`;
L29: }
L30: 
L31: function normalizeWinProxy(server) {
L32:   // 形如 "http=host:port;https=host:port" 或直接 "host:port"
L33:   if (server.includes("=")) {
L34:     const parts = server.split(";");
L35:     const pick = parts.find((p) => /^https=/i.test(p)) ?? parts.find((p) => /^http=/i.test(p));
L36:     if (pick) return withScheme(pick.split("=")[1].trim());
L37:   }
L38:   return withScheme(server.trim());
L39: }
