L41: /**

{
  "name": "@wangkh/deepseek-search-mcp",
  "version": "0.2.0",
  "description": "MCP server exposing DeepSeek tool APIs (web search & fetch, OCR, TTS, ASR) as tools",
  "type": "module",
  "bin": {
    "deepseek-search-mcp": "bin/deepseek-search-mcp.js"
  },
  "files": [
    "bin",
    "src",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "test": "node --test \"test/**/*.test.js\"",
    "prepublishOnly": "npm test"
  },
  "repository": {
    "type": "git",
    "url": "https://gitee.com/ai_1024/deepseek-search-mcp"
  },
  "homepage": "https://gitee.com/ai_1024/deepseek-search-mcp",
  "author": "wangkh <wkh746906141@163.com>",
  "keywords": [
    "mcp",
    "model-context-protocol",
    "deepseek",
    "search",
    "fetch",
    "ocr",
    "tts",
    "asr",
    "speech",
    "web-search",
    "opencode"
  ],
  "license": "MIT",
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "dependencies": {
    "undici": "^8.11.2"
  }
}

import readline from "node:readline";
import { searchWeb, fetchPage, ocrFile, ttsSpeech, asrFile } from "./deepseek.mjs";
import { buildTools } from "./tools.mjs";
import { resolveProxy } from "./proxy.mjs";

export const VERSION = "0.2.0";

/**
 * 构造消息处理器（可注入 env/fetch 以便测试）。
 * 返回 null 表示不需要应答（通知类消息）。
 */
export function createHandler({ env = process.env, fetchImpl = fetch } = {}) {
  const apiKey = env.DEEPSEEK_API_KEY ?? "";
  const baseUrl = env.DEEPSEEK_BASE_URL ?? "https://api.deepseek.com";
  const proxy =
    env.DEEPSEEK_PROXY === "none"
      ? null
      : (env.DEEPSEEK_PROXY && String(env.DEEPSEEK_PROXY).trim()) || resolveProxy({ env });
  const tools = buildTools({
    search: (body) => searchWeb(body, { apiKey, baseUrl, proxy, fetchImpl }),
    fetchPage: (body) => fetchPage(body, { apiKey, baseUrl, proxy, fetchImpl }),
    ocr: (args) => ocrFile(args, { apiKey, baseUrl, proxy, fetchImpl }),
    tts: (args) => ttsSpeech(args, { apiKey, baseUrl, proxy, fetchImpl }),
    asr: (args) => asrFile(args, { apiKey, baseUrl, proxy, fetchImpl }),
  });

  return async function handle(message) {
    const { id, method, params } = message;
    const reply = (result) => ({ jsonrpc: "2.0", id, result });
    if (id === undefined) return null; // notification：无需应答
    switch (method) {
      case "initialize":
        return reply({
          protocolVersion: params?.protocolVersion ?? "2025-06-18",
          capabilities: { tools: {} },
          serverInfo: { name: "deepseek-search-mcp", version: VERSION },
        });
      case "ping":
        return reply({});
      case "tools/list":
        return reply({
          tools: tools.map(({ name, description, inputSchema }) => ({ name, description, inputSchema })),
        });
      case "tools/call": {
        const tool = tools.find((t) => t.name === params?.name);
        if (!tool) {
          return reply({ content: [{ type: "text", text: `未知工具：${params?.name}` }], isError: true });
        }
        try {
          const result = await tool.handler(params.arguments ?? {});
          return reply({ content: [{ type: "text", text: JSON.stringify(result, null, 2) }] });
        } catch (e) {
          return reply({ content: [{ type: "text", text: `错误：${e.message}` }], isError: true });
        }
      }
      default:
        return { jsonrpc: "2.0", id, error: { code: -32601, message: `Method not found: ${method}` } };
    }
  };
}

/** stdio 主循环：stdin 逐行读 JSON-RPC，stdout 逐行回写；日志只走 stderr。 */
export function main() {
  const handle = createHandler();
  const rl = readline.createInterface({ input: process.stdin });
  rl.on("line", (line) => {
    const trimmed = line.trim();
    if (!trimmed) return;
    let msg;
    try {
      msg = JSON.parse(trimmed);
    } catch {
      process.stderr.write("deepseek-search-mcp: 忽略非法 JSON 行\n");
      return;
    }
    void handle(msg)
      .then((res) => {
        if (res) process.stdout.write(JSON.stringify(res) + "\n");
      })
      .catch((e) => {
        process.stderr.write(`deepseek-search-mcp: ${e.message}\n`);
      });
  });
}
